import * as ko from 'knockout';
import { aceAvailable } from '../../widgets/ace/_ace-available';
import { PopupEditorBase } from './_popupEditorBase';
export class CriteriaEditorBase extends PopupEditorBase {
    constructor() {
        super(...arguments);
        this.resizeListeners = [];
        this.editorContainer = ko.observable();
        this.aceAvailable = aceAvailable();
    }
    addResizeListener(listener) {
        this.resizeListeners.push(listener);
    }
    setCriteriaValue(value) {
        if (!this.aceAvailable)
            return;
        const editor = this.editorContainer();
        const session = editor && editor.getSession();
        session && session.setValue(value);
    }
    resizeAceEditor() {
        if (this.aceAvailable && this.editorContainer()) {
            this.editorContainer().resize();
        }
        this.notifyResizeListeners();
    }
    notifyResizeListeners() {
        this.resizeListeners.forEach(listener => listener());
    }
}
